   "titolo": "Pakistan, il governo lancia un sistema hi-tech per monitorare consumi e contrastare i furti di energia",
   "orig": "Govt unveils hi-tech system to manage loadshedding",
   "lead": "Il governo pakistano ha avviato in via preliminare il sistema Asset Performance Management System (APMS), noto anche come Advanced Power Management System, per gestire i tagli di carico e contrastare i furti di elettricità. Il progetto pilota, inizialmente lanciato a Lahore e Kasur, prevede la sincronizzazione del sistema con contatori intelligenti per monitorare i consumi in tempo reale e individuare con precisione i punti di dispersione. Lo riferisce Dawn.",
