   "lead": "Il tenore Hassen Doss ha ricevuto a Roma il Premio per l'eccellenza euro-mediterranea, noto come «Oscar della Mediterraneità». Il riconoscimento gli è stato consegnato il 14 ottobre da Dündar Kesapli, presidente dell'Associazione dei giornalisti del Mediterraneo, in occasione dell'evento dedicato alle personalità che si distinguono per il loro impegno nel dialogo e nel riavvicinamento culturale tra i popoli. Lo riferisce La Presse de Tunisie.",
