   "titolo": "Intesa Sanpaolo, via libera all'aumento di capitale per l'offerta su Mps mentre BlackRock si muove",
   "orig": "Intesa Sp, via libera all?aumento per l?Opas. Si muove Blackrock",
   "lead": "Il consiglio di amministrazione di Intesa Sanpaolo, guidato da Carlo Messina, ha esercitato la delega per avviare l'aumento di capitale funzionale all'offerta pubblica di scambio (Opas) lanciata su Banca Monte dei Paschi di Siena. L'emissione riguarda fino a 5,7 miliardi di azioni, per un valore massimo di 34,3 miliardi di euro, mentre intanto si registra il movimento del colosso finanziario BlackRock e si avvicina la scadenza per il deposito dei titoli in vista dell'assemblea di Siena. Lo riferiscono Il Messaggero – Economia e la Repubblica – Economia.",
   "more": [
    "Le operazioni straordinarie di fusione e acquisizione nel settore bancario comportano complesse manovre finanziarie, tra cui aumenti di capitale e offerte pubbliche di scambio, volte a ridisegnare gli equilibri di mercato e la governance degli istituti di credito coinvolti."
   ],
