   "orig": "Quo vadis architetto? Quando a raccontare sono i figli",
   "lead": "Presentato in anteprima alla Festa del Cinema di Roma, il film documentario «Quo vadis architetto» porta sul grande schermo il racconto della professione e della vita dell'architetto Massimiliano Fuksas attraverso lo sguardo e la regia della figlia Elisa. L'opera si inserisce in un filone di narrazione cinematografica che in passato ha visto altri illustri racconti dedicati a grandi maestri dell'architettura come Kahn e Koolhaas. Lo riferisce Il Giornale dell'Architettura.",
