   "orig": "Beeline Uzbekistan’s parent company to acquire Perfectum for $207 million.",
   "lead": "Il gruppo internazionale di telecomunicazioni VEON, proprietario di Beeline Uzbekistan, ha sottoscritto un accordo per l'acquisizione totale di Rubicon Wireless, la società che opera sotto il marchio Perfectum. L'operazione finanziaria ammonta a circa 207 milioni di dollari, inclusi i debiti societari, e il completamento è previsto entro la fine di ottobre. Lo riferisce Kun.uz (inglese).",
