   "titolo": "Scienziati chiedono un dibattito etico prima di avviare la terraformazione di Marte",
   "orig": "Who speaks for Mars? Scientists call for ethical debate before terraforming begins",
   "lead": "Un gruppo di scienziati ed eticisti planetari olandesi, francesi e statunitensi ha pubblicato un articolo di opinione sulla rivista Eos, avvertendo che la trasformazione di Marte in un mondo simile alla Terra potrebbe distruggere in modo irreversibile le prove scientifiche sulla storia del pianeta e sulla possibile presenza passata di vita extraterrestri prima che venga pienamente esplorato. Lo riferisce Phys.org – Spazio.",
   "more": [
    "La terraformazione è un ipotetico processo ingegneristico planetario volto a modificare l'atmosfera, la temperatura e la superficie di un corpo celeste per renderlo abitabile dagli esseri umani, un tema che solleva complessi interrogativi etici e scientifici sulla conservazione degli ambienti extraterrestri."
   ],
