   "lead": "I ricercatori del Trottier Space Institute della McGill University hanno scoperto che il gas in orbita attorno a Sagittarius A*, il buco nero supermassiccio situato al centro della galassia della Via Lattea, presenta un'elevata concentrazione di metalli. Secondo gli studiosi, tale arricchimento deriva dai materiali dispersi nello spazio dalle esplosioni stellari avvenute nel corso del tempo. Lo riferisce Phys.org – Spazio.",
