   "orig": "US sanctions 5 Chinese entities over ex-Google engineer’s AI trade secrets theft",
   "lead": "Il Dipartimento di Stato americano ha annunciato l'imposizione di sanzioni contro cinque entità cinesi accusate di aver sottratto segreti commerciali ad aziende statunitensi. Tra i soggetti colpiti figurano la Shanghai Zhisuan Technology, fondata dall'ex ingegnere del software di Google Ding Linwei (condannato a gennaio per furto di segreti industriali), e la società di venture capital MiraclePlus. Lo riferisce South China Morning Post – Cina.",
