   "lead": "Hong Kong intende rafforzare la propria posizione come centro finanziario per i titoli in yuan aprendosi a un numero maggiore di emittenti di debito sovrano. In occasione della riunione ministeriale finanziaria dell'Apec, la città intende valorizzare i vantaggi dei propri mercati e i costi di raccolta competitivi del mercato obbligazionario dim sum. Lo riferisce South China Morning Post – Economia.",
