   "id": "z8123ede2",
   "sez": "prima",
   "titolo": "Zelensky accusa gli Stati Uniti di ritardare la consegna dei missili Patriot",
   "orig": "Zelensky: Usa frenano consegne Patriot",
   "lead": "Il presidente ucraino Volodymyr Zelensky ha accusato gli Stati Uniti di rallentare la consegna dei sistemi di difesa aerea Patriot, sottolineando che non si tratta di un problema tecnico. I missili in questione risultano già pagati dagli alleati europei di Kiev. L'accusa giunge in un momento di crescente tensione nelle relazioni diplomatiche tra Washington e il governo ucraino, mentre la difesa dei cieli dell'Ucraina rimane cruciale per contrastare gli attacchi aerei. Il ritardo nelle forniture militari rischia di indebolire la protezione delle infrastrutture strategiche del Paese.",
   "more": [
    "I sistemi Patriot sono tra i dispositivi di difesa antimissile più avanzati al mondo, capaci di intercettare vettori balistici e da crociera. La loro presenza è fondamentale per coprire i centri urbani e le reti energetiche ucraine durante il conflitto in corso con la Russia."
   ],
