   "id": "z1c01f067",
   "sez": "mondo",
   "titolo": "La Corte Suprema degli Stati Uniti esaminerà un caso sulle ammissioni scolastiche e l'appartenenza etnica",
   "orig": "US Supreme Court to hear case on race in school admissions",
   "lead": "La Corte Suprema degli Stati Uniti ha accettato di esaminare un ricorso relativo ai criteri di ammissione scolastica basati sull'appartenenza etnica. Un gruppo di genitori sostiene che le attuali politiche locali favoriscano gli studenti afroamericani e ispanici, finendo per penalizzare e limitare le candidature dei giovani di origine asiatica. La decisione della massima istanza giudiziaria americana potrebbe ridefinire le regole di accesso negli istituti d'istruzione di tutto il Paese, riaprendo un acceso confronto sui programmi di discriminazione positiva nel sistema educativo statunitense. Lo riferisce Al Jazeera.",
   "more": [
    "Il dibattito sulle politiche di ammissione nelle scuole e nelle università statunitensi dura da decenni. I sostenitori ritengono la considerazione dell'etnia necessaria per promuovere la diversità, mentre i critici evidenziano il rischio di discriminazioni indirette verso specifici gruppi di studenti."
   ],
