   "id": "z22ba432d",
   "sez": "cultura",
   "titolo": "L'artigiano partenopeo dell'ombrello amato dalle personalità internazionali",
   "orig": "The umbrella maker of Naples: “From King Charles to Stallone, my creations are loved across the globe”",
   "lead": "A Napoli l'artigiano Mario Talarico, erede di una storica bottega familiare fondata nel 1860 in via Toledo, rivendica il valore globale dell'artigianato partenopeo. Le sue creazioni su misura, che hanno conquistato clienti illustri come re Carlo III e l'attore Sylvester Stallone, dimostrano come un'antica tradizione manuale possa conservare un futuro economico rilevante, arrivando a quotazioni fino a ventimila euro per un singolo ombrello fatto a mano. L'artigiano evidenzia la capacità della lavorazione classica di resistere al tempo e alla produzione industriale. Lo riferisce la Repubblica.",
   "more": [
    "L'artigianato artistico e su misura rappresenta un patrimonio culturale ed economico distintivo di diverse città italiane. La lavorazione manuale di accessori di lusso combina competenze tradizionali secolari con un mercato internazionale orientato a prodotti unici ed esclusivi."
   ],
