   "id": "zeb1ff31f",
   "sez": "economia",
   "titolo": "La maggioranza fissa le priorità della manovra mentre slitta l'intesa sul contributo delle banche",
   "orig": "La maggioranza fissa le priorità della manovra, si cerca intesa su banche",
   "lead": "La maggioranza di governo in Italia ha definito le linee guida prioritarie per la nuova legge di bilancio, mentre prosegue la ricerca di un accordo sul contributo del settore bancario. Il via libera al testo definitivo nel Consiglio dei ministri è stato slittato per consentire il prosieguo delle trattative in corso con le istituzioni dell'Unione Europea. Il confronto politico resta concentrato sul reperimento delle risorse necessarie a finanziare le misure fiscali ed economiche della manovra finanziaria per il prossimo anno. Lo riferisce ANSA.",
   "more": [
    "La legge di bilancio definisce le entrate e le uscite dello Stato per l'anno successivo. Il dialogo con le autorità europee garantisce il rispetto dei vincoli di finanza pubblica e dei parametri del Patto di stabilità sulle coperture economiche previste."
   ],
