   "id": "z1ffce78a",
   "sez": "organizzazioni",
   "titolo": "Al via in Armenia i lavori della Conferenza ONU sulla tutela della biodiversità",
   "orig": "Protecting Earth’s fragile biodiversity takes spotlight at Armenia talks",
   "lead": "A Yerevan, in Armenia, si sono aperti i lavori della Conferenza delle Nazioni Unite sulla biodiversità. Il vertice internazionale mette al centro delle discussioni la protezione degli ecosistemi terrestri e il contrasto alla perdita di specie animali e vegetali. I dirigenti dell'ONU hanno richiamato i Paesi partecipanti alla necessità di adottare azioni urgenti e vincolanti per tutelare il pianeta, evidenziando come il degrado ambientale e la diminuzione della biodiversità stiano mettendo a rischio il benessere e il futuro economico di miliardi di persone nel mondo.",
   "more": [
    "La Convenzione sulla diversità biologica delle Nazioni Unite raccoglie quasi tutti i Paesi del mondo per concordare strategie globali di conservazione della natura. Gli incontri puntano a fissare obiettivi condivisi per arrestare la distruzione degli habitat e garantire un uso sostenibile delle risorse naturali."
   ],
