   "id": "z3fe2bd7a",
   "sez": "viaggi",
   "titolo": "La Thailandia attende fino a 5,5 milioni di turisti cinesi nonostante i recenti avvisi di viaggio",
   "orig": "Chinese travel alert unlikely to affect arrivals this year",
   "lead": "In Thailandia l'Autorità per il Turismo e l'Associazione degli Agenti di Viaggio Thai hanno rassicurato sul flusso turistico, stimando tra cinque e cinque milioni e mezzo gli arrivi dalla Cina entro la fine dell'anno. La precisazione giunge dopo l'emissione di un nuovo avviso da parte delle autorità cinesi relativo a truffe di lavoro e frodi nel Paese del Sud-est asiatico. Secondo le organizzazioni turistiche locali, l'allarme cinese è rivolto prevalentemente a profili specifici e non intaccherà l'afflusso complessivo dei turisti. Lo riferisce Bangkok Post.",
   "more": [
    "Il turismo cinese rappresenta una quota strategica per l'economia della Thailandia. Gli avvisi di viaggio emessi da Pechino su casi di frodi o criminalità informatica nell'area del Sud-est asiatico possono influenzare la percezione della sicurezza da parte dei visitatori."
   ],
