   "sez": "spazio",
   "titolo": "L'impatto dell'attività umana sul ciclo dell'acqua della Terra",
   "orig": "The Human Fingerprint on Earth’s Water Cycle",
   "lead": "Le attività umane sono ormai strettamente connesse alle modalità con cui l'acqua viene distribuita attraverso i continenti del pianeta. Un recente studio condotto dalla NASA a Washington analizza in dettaglio gli effetti antropici sul ciclo idrologico terrestre, evidenziando come i cambiamenti impressi dall'uomo siano diventati particolarmente rilevanti. Lo riferisce Nasa.",
   "more": [
    "Il ciclo dell'acqua descrive il continuo movimento dell'acqua sulla superficie terrestre, nell'atmosfera e nel sottosuolo. L'azione dell'uomo, attraverso la costruzione di dighe, l'agricoltura intensiva e i cambiamenti climatici, influisce in modo significativo sulla sua distribuzione globale."
   ],
