   "titolo": "I chip basati su architettura RISC-V di Alibaba superano quota sei miliardi di unità",
   "orig": "Alibaba’s RISC-V IP powers over 6 billion shipped chips as tech giant targets AI, autos",
   "lead": "La divisione di ricerca Damo Academy del gruppo Alibaba ha annunciato che le spedizioni di chip basati sulla tecnologia open source RISC-V hanno superato i sei miliardi di unità. Il traguardo, comunicato durante una conferenza a Shenzhen, testimonia la spinta del gigante tecnologico verso l'intelligenza artificiale e i sistemi per l'automotive. Lo riferisce South China Morning Post – Tecnologia.",
   "more": [
    "L'architettura RISC-V è un'istruzione di tipo open source che consente alle aziende di sviluppare processori personalizzati senza dover pagare licenze proprietarie, diventando un pilastro strategico per l'industria dei semiconduttori."
   ],
