   "id": "z55997401",
   "sez": "economia",
   "titolo": "La spinta per la lavorazione dei minerali in Africa attira investimenti ma sconta il problema energetico",
   "orig": "Africa’s minerals value-add drive interests investors but faces energy hurdle",
   "lead": "I Paesi africani stanno spingendo le compagnie minerarie a costruire raffinerie e fonderie direttamente nel continente per aumentare il valore delle materie prime estratte, come la bauxite in Guinea. Tuttavia, funzionari governativi e industriali avvertono che la mancanza di energia elettrica economica e affidabile rischia di frenare gli investimenti, ostacolando il processo di industrializzazione che richiede grandi quantità di potenza energetica. Lo riferisce Club of Mozambique.",
   "more": [
    "La trasformazione locale delle risorse minerarie rappresenta una strategia chiave per molti Stati africani per trattenere una maggiore quota di ricchezza economica derivata dall'esportazione di materie prime. Tuttavia, la storica carenza di infrastrutture energetiche stabili e diffuse nel continente costituisce uno dei principali ostacoli strutturali allo sviluppo di impianti industriali ad alto consumo di energia."
   ],
