   "id": "z26bf73eb",
   "sez": "spazio",
   "titolo": "La NASA migliora le analisi su vibrazioni e sollecitazioni per i razzi spaziali",
   "orig": "NASA Improves Shock, Vibration Analysis",
   "lead": "I tecnici del Dynamic Environments Group della NASA impegnati nelle operazioni di lancio stanno migliorando i metodi per analizzare e prevedere l'impatto di vibrazioni, scosse e flessioni estreme subite dai razzi durante il volo verso lo spazio. L'obiettivo è garantire che i veicoli spaziali e i delicati strumenti scientifici trasportati possano resistere alle intense forze meccaniche prima di lasciare il suolo. Lo riferisce Nasa.",
   "more": [
    "Durante il decollo e la fase di ascesa attraverso l'atmosfera, i vettori spaziali sono sottoposti a sollecitazioni strutturali straordinarie causate dalla pressione aerodinamica e dalla spinta dei motori. Lo studio avanzato delle sollecitazioni dinamiche consente agli ingegneri di progettare strutture più resistenti e di proteggere i carichi utili scientifici da danni meccanici irreparabili."
   ],
