   "id": "z6fdc93e4",
   "sez": "dibattito",
   "titolo": "Allarmi bomba nelle scuole in Italia e in Europa: decine di evacuazioni dopo e-mail minatorie",
   "orig": "Psicosi bomba nelle scuole di mezza Europa: allarmi via e-mail e decine di evacuazioni da Nord a Sud Italia fino al Regno Unito",
   "lead": "Un'azione coordinata e su vasta scala, veicolata attraverso la posta elettronica, ha provocato la psicosi e decine di evacuazioni in centinaia di plessi scolastici situati tra l'Italia e diversi Paesi europei. Gli allarmi bomba digitali hanno interessato numerose scuole da Nord a Sud della penisola fino al Regno Unito, gettando nel terrore studenti e personale scolastico. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Negli ultimi anni si sono registrati ripetuti episodi di falsi allarmi e minacce informatiche rivolte contro istituzioni scolastiche e luoghi pubblici in Europa, spesso gestiti tramite messaggi di posta elettronica anonimi. Tali azioni attivano automaticamente i protocolli di emergenza previsti dalle autorità di polizia, comportando l'evacuazione preventiva degli edifici e complesse verifiche da parte delle forze dell'ordine per accertare l'eventuale presenza di ordigni."
   ],
