   "id": "z7eb6c4f0",
   "sez": "musica",
   "titolo": "A$AP Rocky annuncia un nuovo progetto musicale ispirato a Spike Lee e Malcolm X",
   "orig": "A$AP Rocky: «Il prossimo progetto ispirato a Spike Lee e Malcolm X»",
   "lead": "Il rapper A$AP Rocky ha annunciato che il suo prossimo progetto discografico trarrà ispirazione da figure storiche e culturali come Spike Lee e Malcolm X. Nel frattempo, l'artista si prepara alla pubblicazione di 'Disc 2', descritto come un'estensione dell'album 'Don’t Be Dumb'. Ha inoltre condiviso riflessioni personali sulla sua famiglia, raccontando che i suoi figli lo hanno visto esibirsi sul palco per la prima volta. Lo riferisce Rolling Stone Italia.",
   "more": [
    "L'ispirazione tratta da personalità di spicco della cultura afroamericana e del cinema d'impegno civile, come Malcolm X e Spike Lee, caratterizza spesso la produzione artistica e visiva nel panorama hip-hop contemporaneo. Questo approccio unisce la ricerca musicale a narrazioni di forte identità culturale e sociale."
   ],
