   "id": "z007fe264",
   "sez": "tech",
   "titolo": "Ottimizzare internet per gli agenti IA potrebbe peggiorare l'esperienza per gli utenti umani",
   "orig": "Making the internet better for AI agents might make it worse for everyone else",
   "lead": "Fino a poco tempo fa gli utenti di internet potevano essere suddivisi unicamente in due categorie: le persone e i bot. Con la crescente diffusione dei sistemi di intelligenza artificiale, i siti web stanno valutando modifiche strutturali per facilitare l'accesso ai contenuti da parte degli agenti IA, ma gli esperti avvertono che tali ottimizzazioni rischiano di rendere la rete meno fruibile e peggiore per gli utenti umani tradizionali. Lo riferisce MIT Technology Review.",
   "more": [
    "Lo sviluppo dei software basati sull'intelligenza artificiale richiede la raccolta e l'elaborazione di enormi quantità di dati presenti sul web attraverso strumenti di scansione automatica. La necessità di regolare questo traffico informatico sta spingendo gli sviluppatori di siti web a ripensare i protocolli di accesso, bilanciando le esigenze di automazione con la tutela della privacy e dell'esperienza di navigazione degli utenti in carne e ossa."
   ],
