   "sez": "musica",
   "titolo": "La figlia di Levon Helm avvia una controquerela contro i Levon Helm Studios",
   "orig": "Levon Helm’s Daughter Countersues Levon Helm Studios",
   "lead": "La figlia del compianto batterista Levon Helm ha presentato una controquerela nei confronti della struttura di gestione dei Levon Helm Studios. L'azione legale sostiene che il suo successore abbia assunto il controllo del celebre locale e studio di registrazione musicale ricorrendo a metodi impropri. Lo riferisce Pitchfork.",
   "more": [
    "I Levon Helm Studios, situati nello stato di New York, sono stati fondati dal batterista del gruppo The Band e rappresentano un luogo storico per la musica rock e folk americana. Le controversie legali sulla gestione patrimoniale e sulla proprietà dei beni artistici di artisti famosi coinvolgono spesso gli eredi e i fiduciari nominati per amministrare l'eredità culturale."
   ],
