   "sez": "cultura",
   "titolo": "Le teorie storiche dietro l'animismo e la visione di Hayao Miyazaki in Princess Mononoke",
   "orig": "Miyazaki Hayao’s Animism: The Historical Theories That Shaped “Princess Mononoke”",
   "lead": "Il capolavoro cinematografico Princess Mononoke di Hayao Miyazaki ha messo in luce un approccio alla rappresentazione della natura marcatamente differente rispetto a quello del suo predecessore Osamu Tezuka. Il film, analizzato a Tokyo, ha messo in discussione la storiografia giapponese tradizionale introducendo la cultura delle foreste antiche e figure itineranti medievali, sostenuto da una visione del mondo animista ispirata a teorie storiche audaci. Lo riferisce Nippon.com.",
   "more": [
    "L'animismo è una credenza spirituale secondo cui gli oggetti, i luoghi e le creature possiedono un'anima o una essenza spirituale distinta. Nella cultura giapponese e nella tradizione shintoista, questo legame profondo con gli elementi naturali ha influenzato profondamente la narrazione artistica e cinematografica, ponendo spesso l'accento sul difficile equilibrio tra lo sviluppo umano e la conservazione degli ambienti naturali."
   ],
