   "id": "z8e92c5eb",
   "sez": "tech",
   "titolo": "Spotify lancia gli audiolibri in Italia: costi, funzionamento e opzioni di ascolto",
   "orig": "Spotify, quanto costano gli audiolibri in Italia: come funzionano, chi ha 12 ore gratis e tutti gli abbonamenti",
   "lead": "Dal 7 ottobre la piattaforma Spotify ha introdotto ufficialmente gli audiolibri anche in Italia, mettendo a disposizione degli utenti un catalogo di oltre 14.000 opere da ascoltare direttamente dall'applicazione. L'offerta, presentata a Roma, prevede formule in abbonamento e opzioni specifiche che includono dodici ore di ascolto gratuito per determinati utenti. Lo riferisce Il Messaggero – Tecnologia.",
   "more": [
    "Il mercato degli audiolibri sta registrando una forte crescita digitale grazie alla diffusione degli smartphone e alla comodità dell'ascolto in mobilità durante il lavoro o i viaggi. L'ingresso di grandi piattaforme di streaming musicale in questo settore amplia la concorrenza e favorisce la digitalizzazione dell'editoria."
   ],
