   "orig": "Halmar completes Yankee Stadium stop on $965M subway upgrades",
   "lead": "L'impresa di costruzioni Halmar ha completato i lavori presso la stazione dello Yankee Stadium nell'ambito di un progetto di aggiornamento della metropolitana dal valore complessivo di 965 milioni di dollari. L'azienda prevede di ultimare gli interventi sulle restanti dodici stazioni entro l'inizio del 2027 a Washington. Lo riferisce Construction Dive.",
