   "orig": "Listen to BA Bake Club’s Podcast on Glazed Apple Pie Fritters",
   "lead": "Nell'ultimo episodio del podcast del BA Bake Club registrato a New York, Jesse e Shilpa hanno discusso dell'arte della frittura insieme a Mark Bittman e a sua figlia Kate Bittman, approfondendo la preparazione delle frittelle di mele glassate. Lo riferisce Bon Appétit.",
