   "lead": "Una strada di Brooklyn è stata intitolata a Billy Jones, defunto cofondatore del locale Baby's All Right. L'iniziativa, celebrata a New York, riconosce il contributo significativo offerto da Jones alla scena musicale locale. Lo riferisce Pitchfork.",
