   "lead": "Il rapper e cantante Swae Lee ha annunciato lo svolgimento del tour australiano Same Difference, previsto per il mese di gennaio. L'artista terrà cinque concerti lungo la costa orientale e occidentale per promuovere il suo album di debutto solista, come riportato a Los Angeles. Lo riferisce Billboard.",
