   "id": "zd457f23a",
   "sez": "prima",
   "titolo": "Milano, serrande abbassate nel quadrilatero del lusso dopo le violenze urbane",
   "orig": "Paura a Milano, chiusi i negozi del lusso",
   "lead": "A Milano le boutique dell'alta moda e i negozi del centro storico, tra cui Chanel, Hermès e Pomellato, hanno abbassato anticipatamente le saracinesche lunedì pomeriggio per il timore di nuovi assalti. L'allerta è scattata a seguito dei violenti disordini del fine settimana, caratterizzati da devastazioni che hanno causato danni superiori a un milione di euro. La procura milanese ha qualificato gli attacchi come azioni di rara violenza, mentre le forze dell'ordine hanno proceduto ad almeno cinquanta arresti, coinvolgendo prevalentemente giovanissimi e minorenni.",
   "more": [
    "Il quadrilatero della moda di Milano, imperniato su vie come via Montenapoleone e via della Spiga, costituisce il cuore commerciale dell'alta moda italiana ed europea. La tutela della sicurezza in quest'area urbana coinvolge la prefettura, il comune e le autorità di pubblica sicurezza per la salvaguardia di residenti e commercianti."
   ],
