   "id": "zde0d5fae",
   "sez": "prima",
   "titolo": "Scontri di Milano, il governo studia un decreto per le forze dell'ordine",
   "orig": "Salvini:più libertà azione alle forze dell'ordine",
   "lead": "Il governo italiano lavora a un provvedimento d'urgenza per rafforzare le dotazioni e i poteri operativi delle forze di sicurezza in seguito ai gravi disordini di piazza a Milano, costati il ferimento di quasi duecento agenti. Il ministro Matteo Salvini ha sollecitato maggiore libertà d'azione, inclusi idranti e taser, mentre il presidente della Repubblica Sergio Mattarella ha definito le violenze inaccettabili, chiedendo un'analisi approfondita. Nel Consiglio dei ministri è previsto l'esame di misure che contemplano il fermo preventivo a ventiquattro ore e poteri di polizia per i militari.",
   "more": [
    "L'ordine pubblico in Italia è regolato dalle leggi dello Stato sotto il coordinamento del ministero dell'Interno e delle prefetture. L'eventuale attribuzione di qualifiche di pubblica sicurezza ai militari impiegati nelle città richiede un apposito intervento normativo primario, solitamente varato tramite decreto-legge deliberato dal governo."
   ],
