   "sez": "mondo",
   "titolo": "Elezioni in Israele, Netanyahu mostra il sostegno di Trump prima del voto",
   "orig": "À l'approche des législatives en Israël, Netanyahu met en avant son alliance avec Trump",
   "lead": "A una settimana dalle elezioni legislative israeliane del 27 ottobre, il primo ministro Benjamin Netanyahu ha pubblicato sui propri profili social la registrazione di un colloquio telefonico intercorso con Donald Trump. Nel dialogo, il presidente statunitense loda calorosamente il leader del Likud definendolo un grande combattente e pronostica per lui un netto trionfo alle urne. Il gesto intende rinsaldare il patto politico tra i due leader di destra proprio mentre le rilevazioni demoscopiche segnalano un testa a testa serrato che rende particolarmente incerto l'esito della consultazione parlamentare.",
   "more": [
    "La Knesset è il parlamento monocamerale israeliano, composto da 120 deputati eletti su base proporzionale nazionale. La formazione di una maggioranza di governo richiede il controllo di almeno sessantuno seggi, un obiettivo che frequentemente impone lunghe trattative tra partiti diversi per costruire coalizioni stabili."
   ],
