   "sez": "mondo",
   "titolo": "Trump sfrutta le violenze in Francia per la campagna elettorale negli Stati Uniti",
   "orig": "Trump attacks ‘migrants and communists’ as he tries to exploit France unrest",
   "lead": "Nel corso di un comizio tenutosi in Kansas, Donald Trump ha preso di mira i disordini che scuotono la Francia, descrivendo la repubblica europea come una nazione saccheggiata e bruciata da migranti, estremisti e comunisti. Il presidente statunitense ha utilizzato la crisi d'oltreoceano per difendere la candidatura del repubblicano Roger Marshall al Senato e per attaccare duramente i democratici in vista delle imminenti elezioni di metà mandato. Trump ha presentato gli scontri francesi come un monito per i cittadini americani a difesa delle frontiere nazionali.",
   "more": [
    "Le elezioni di metà mandato negli Stati Uniti rinnovano l'intera Camera dei rappresentanti e un terzo dei seggi del Senato a metà del quadriennio presidenziale. Rappresentano un banco di prova decisivo per verificare il consenso dell'amministrazione in carica e per determinare il controllo dei rami del Congresso."
   ],
