 "contesti": {
  "z2493abe1": "Nelle ultime settimane la Terra ha iniziato ad attraversare la densa fascia di detriti cometari, provocando un graduale incremento delle meteore visibili. Gli osservatori astronomici internazionali hanno monitorato la progressione del fenomeno, segnalando la finestra temporale migliore per avvistare il picco di attività nel corso della seconda metà di ottobre.",
  "z560bf863": "Nelle scorse settimane entrambe le compagini hanno consolidato la propria posizione nei rispettivi tornei nazionali e nelle giornate inaugurali europee. L'avvicinamento al match è stato scandito dai dibattiti sulle candidature al vertice del calcio mondiale, con i giovani interpreti delle due rose protagonisti di prove determinanti.",
  "zd457f23a": "Durante il fine settimana il centro urbano milanese è stato teatro di gravi scontri e saccheggi mirati contro punti vendita ed esercizi commerciali. Le immagini degli assalti sono circolate sui social network provocando appelli a nuove mobilitazioni, mentre il sindaco Sala ha avvertito che la fase critica non è ancora superata.",
  "zde0d5fae": "Gli scontri del fine settimana nel capoluogo lombardo hanno provocato devastazioni e numerosi feriti tra i reparti schierati, innescando una rapida reazione politica. I vertici istituzionali hanno avviato interlocuzioni immediate per concordare una cornice normativa che permetta di prevenire nuovi focolai di guerriglia urbana.",
  "ze1930ee8": "Lo scontro è esploso lo scorso 30 settembre quando Ronaldo ha lasciato il ritiro lusitano nel mezzo della competizione continentale. Nei giorni successivi la stampa internazionale aveva ipotizzato sanzioni più severe, fino a sei mesi di stop, prima che il tribunale sportivo formalizzasse una pena più contenuta.",
  "z760180b3": "La campagna elettorale israeliana è giunta alla sua fase culminante in un quadro di forte polarizzazione interna. Trump ha rinnovato pubblicamente il proprio appoggio a Netanyahu, mentre gli osservatori politici discutono l'effettivo impatto del sostegno estero sull'elettorato moderato o indeciso a ridosso del voto.",
  "zfab24d4a": "Nelle ultime settimane la Francia ha registrato estese manifestazioni contro il carovita e le condizioni scolastiche degenerate poi in disordini urbani. La crisi transatlantica ha subito riacceso la contesa ideologica internazionale, spingendo esponenti conservatori negli Stati Uniti e nell'Europa orientale a rilanciare strette sull'immigrazione.",
  "z1ee682b0": "Nel corso del fine settimana manifestazioni nate per denunciare il carovita e le carenze nei servizi pubblici sono degenerate in scontri diffusi con le forze dell'ordine e in atti di saccheggio. L'estensione dei tafferugli in centri come Parigi e Nizza ha costretto il governo a varare restrizioni immediate.",
  "ze3fc4fdf": "Negli ultimi giorni l'Africa orientale ha registrato una ripresa di contagi da virus Ebola, spingendo le autorità sanitarie locali ad attivare protocolli d'emergenza. L'epidemia ha provocato preoccupazioni internazionali e l'aggiornamento dei livelli di allerta per i viaggiatori diretti nella regione da parte di governi stranieri.",
  "zd9965ddb": "Dall'inizio della guerra nel febbraio 2022, numerosi atleti ucraini hanno espresso pubblicamente le difficoltà personali e professionali derivanti dal conflitto. Svitolina ha più volte partecipato a iniziative benefiche e di testimonianza internazionale a sostegno della popolazione coinvolta nei combattimenti.",
  "z56476f23": "Negli ultimi giorni diverse manifestazioni di protesta contro il carovita e la gestione dei servizi pubblici a Milano sono degenerate in violenti disordini urbani, con danni ad attività commerciali e scontri con le forze dell'ordine. Il governo ha dunque convocato vertici straordinari per pianificare interventi di contrasto ai disordini estendibili ad altre città.",
  "z8123ede2": "Nelle ultime settimane, le forze russe hanno intensificato i bombardamenti aerei contro le infrastrutture critiche e le città ucraine, aggravando la crisi energetica del Paese. Di fronte a questa offensiva, Kiev ha ripetutamente invocato un rafforzamento urgente della difesa antiaerea da parte dei partner occidentali. Nonostante i finanziamenti europei per l'acquisto di sistemi missilistici avanzati, la consegna effettiva dei dispositivi da parte di Washington ha subito ripetuti rinvii, alimentando frizioni diplomatiche."
 },
